/*
   компонент, для фильтрации таблицы
   пропсы:
      fullData - полные данные
      filtering - функция обновления данных таблицы
*/
const Filter = (props) => {
    const handleSubmit = (event) => {
        event.preventDefault();

        const filterField = {
            "Название": event.target["name"].value.toLowerCase(),
            "Место обитания": event.target["place"].value.toLowerCase(),
            "Вес": [event.target["weight_from"].value, event.target["weight_to"].value],
            "Размер": [event.target["size_from"].value, event.target["size_to"].value],
            "Продолжительность жизни": [event.target["life_from"].value, event.target["life_to"].value],
            "Год открытия": [event.target["year_from"].value, event.target["year_to"].value]
        };

        const filterNums = (num, min, max) => {
            if (min === "") {
                min = -Infinity;
            }
            if (max === "") {
                max = Infinity;
            }

            num = Number(num);
            min = Number(min);
            max = Number(max);

            return num >= min && num <= max;
        }

        let arr = props.fullData;
        for (const key in filterField) {
            arr = arr.filter(item =>
                ["Вес", "Размер", "Продолжительность жизни", "Год открытия"].includes(key)
                    ? filterNums(item[key], filterField[key][0], filterField[key][1])
                    : item[key].toLowerCase().includes(filterField[key])
            );
        }

        props.filtering(arr);
    }

    const handleReset = () => {
        props.filtering(props.fullData);
    }

    return (
        <div className="filter-block">
            <form className="filter-form" onSubmit={ handleSubmit } onReset={ handleReset }>

                <label>Название:
                    <input name="name" type="text"/>
                </label>

                <label>Место обитания:
                <input name="place" type="text"/>
                </label>

                <label>Вес от: </label>
                <input name="weight_from" type="number" step="any"/>
                <label> до: </label>
                <input name="weight_to" type="number" step="any"/>


                <label>Размер от: </label>
                <input name="size_from" type="number" step="any"/>
                <label> до: </label>
                <input name="size_to" type="number" step="any"/>


                <label>Продолжительность жизни от: </label>
                <input name="life_from" type="number" step="any"/>
                <label> до: </label>
                <input name="life_to" type="number" step="any"/>


                <label>Год открытия от: </label>
                <input name="year_from" type="number"/>
                <label> до: </label>
                <input name="year_to" type="number"/>

                <div className="filter-actions">
                    <button type="submit">Найти</button>
                    <button type="reset">Очистить фильтр</button>
                </div>
            </form>
        </div>
    )
}

export default Filter;
